-- 协议种子数据（用户协议/隐私政策/会员协议/自律声明/防骗提醒）
-- =============================================
INSERT IGNORE INTO `agreements` (`type`, `title`, `content`, `isActive`) VALUES
('USER_AGREEMENT', '用户协议', '<p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">\"{{appName}}\"服务协议</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">欢迎使用\"{{appName}}\"提供的服务。在此特别提醒您（用户）在注册成为用户之前，请认真阅读本《用户协议》（以下简称\"协议\"），确保您充分理解本协议中各条款。请您审慎阅读并选择接受或不接受本协议。如对协议内容有任何异议的，应向本平台咨询。您的注册、登录、使用等行为将视为对本协议的接受，即与本平台缔结了本协议，本协议即对用户产生约束。本协议约定本平台与用户之间关于\"{{appName}}\"服务协议（以下简称\"服务\"）的权利义务。\"用户\"是指注册、登录、使用本服务的个人。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\"> 一、账号注册 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">1. 用户保证，在用户完成注册程序或以其他本平台允许的方式实际使用\"{{appName}}\"的服务时，用户应当是具备完全民事权利能力和完全民事行为能力的自然人、法人或其他组织。若用户不具备前述主体资格，则用户及用户的监护人应承担因此而导致的一切后果，同时本平台将保留追究用户及其监护人民事、刑事责任等权利，且本平台有权注销(永久冻结)用户的\"{{appName}}\"账号,账号内的剩余费用不予退回，并有权向用户及用户的监护人索赔。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">2. 申请注册成为\"{{appName}}\"的会员应同时满足下列全部条件： </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(1) 在注册之日以及此后使用\"{{appName}}\"服务期间必须以恋爱或者婚姻为目的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(2) 在注册之日以及此后使用\"{{appName}}\"服务期间必须是单身状态，包括未婚、离异或是丧偶； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(3) 在注册之日必须年满18周岁以上。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\"> 3. 在用户注册及使用本服务时，本平台需要搜集能识别用户身份的个人信息以便本平台可以在必要时联系用户，或为用户提供更好的使用体验。本平台搜集的信息包括但不限于用户的姓名、性别、年龄、出生日期、身份证号、地址、学校情况、公司情况、所属行业、兴趣爱好、常出没的地方、个人说明；本平台同意对这些信息的使用将受限于第三条用户个人隐私信息保护的约束。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">4. 持有大陆地区身份证的实名认证用户指已经通过全国公民身份信息系统核实。该用户提供的姓名，性别，年龄及身份证号码相符，用户可以申请与其交换身份证照片信息，并与其本人形象照比对，确认其为该证件的所有者。 港澳台及海外实名认证用户指提交了其身份证件的扫描或传真件，但因目前尚无可用的核实渠道，本平台暂时无法核实其证件真伪。婚姻状态、职业、学历、收入等信息目前暂不能核实。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">5. 用户在使用\"{{appName}}\"服务过程中，所产生的应纳税赋，以及一切硬件、软件、服务及其它方面的费用，均由用户独自承担。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">6. 在用户按照注册页面提示填写信息、阅读并同意本协议并完成全部注册程序后或以其他本平台允许的方式实际使用\"{{appName}}\"服务时即成为\"{{appName}}\"用户。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">7. \"{{appName}}\"是一款面向有明确结婚意向的单身人士的实名制移动社交产品，根据需要用户向\"{{appName}}\"提交可以证实自己个人信息真实性的包括但不限于用户的身份证件号码及正反面照片、护照证件号码及照片、学历学位证书正面照片、房产证件正面照片、汽车行驶证件正面照片，\"{{appName}}\"有权对用户提交的认证信息进行审核并且确认通过或者否决通过。用户无法通过\"{{appName}}\"的信息认证审核将无法使用\"{{appName}}\"提供的包括但不限于即时通讯、关注他人产品功能，但可以查看其他会员的公开资料及使用\"{{appName}}\"提供的条件搜索功能。\"{{appName}}\"将对用户提交的用于个人信息真实性认证的资料进行严格的保密。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">二、服务内容 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">1. 本服务的具体内容由本平台根据实际情况提供，包括但不限于授权用户通过其账号进行即时通讯、关注他人、发布留言。本平台可以对其提供的服务予以变更，且本平台提供的服务内容可能随时变更；用户将会收到本平台关于服务变更的通知。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">2. 本平台提供的服务包含免费服务与收费服务。用户可以通过付费方式购买收费服务，具体方式为：用户通过\"{{appName}}\"平台提供的付费途径支付一定数额的人民币，然后根据\"{{appName}}\"公布的资费标准购买用户欲使用的收费服务，从而获得收费服务使用权限。对于收费服务，本平台会在用户使用之前给予用户明确的提示，只有用户根据提示确认其同意按照前述支付方式支付费用并完成了支付行为，用户才能使用该等收费服务。支付行为的完成以第三方支付平台生成\"支付已完成\"的确认通知为准。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">3. 对于利用\"{{appName}}\"服务进行非法活动，或其言行(无论线上或者线下的)背离真诚交友目的，或违反用户使用规范的，本平台将严肃处理，包括但不限于采取将其列入黑名单、将其被投诉的情形公之于众、删除用户帐号、移送相关司法机关查办等措施。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">4. 用户在\"{{appName}}\"上传或张贴的非个人隐私内容(包括但不限于照片、文字、交友成功用户的成功故事等)，视为用户授予本平台免许可费、非独家及可完全再授权之权利，本平台有权在全球为展示、传播及推广前述张贴内容的目的，对上述内容进行复制、修改、改写、改编、发行、翻译、创造衍生性著作、出版等。或将前述内容(部分或全部)加以散布、展示，或放入利用任何现在已知和未来开发出之形式、媒体和科技之其他著作物当中。本平台亦有权在IPTV、互联网电视展示的\"{{appName}}\"页面上使用上述内容。该使用权持续至用户书面通知本平台不得继续使用，且本平台实际收到该等书面通知时止。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">5. 基于科学技术的不断发展，本平台可通过与第三方合作的方式，通过IPTV、互联网电视等为用户提供网络衍生服务。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">三、用户隐私权保护 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">1. 用户在注册账号或使用本服务的过程中，可能需要填写或提交一些必要的信息，如法律法规、规章规范性文件（以下称\"法律法规\"）规定的需要填写的身份信息。如用户提交的信息不完整或不符合法律法规的规定，则用户可能无法使用本服务或在使用本服务的过程中受到限制。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">2. 个人隐私信息是指涉及用户个人身份或个人隐私的信息，比如，用户身份证件号码、手机号码、手机设备识别码、IP地址、学历学位证书照片，身份证件照片、房产证照片、汽车行驶证照片、用户聊天记录。非个人隐私信息是指用户对本服务的操作状态以及使用习惯等明确且客观反映在本平台服务器端的基本记录信息、个人隐私信息范围外的其它普通信息，以及用户同意公开的上述隐私信息。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">3. 尊重用户个人隐私信息的私有性是本平台的一贯制度，本平台将采取技术措施和其他必要措施，确保用户个人隐私信息安全，防止在本服务中收集的用户个人隐私信息泄露、毁损或丢失。在发生前述情形或者本平台发现存在发生前述情形的可能时，将及时采取补救措施。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">4. 本平台未经用户同意不向任何第三方公开、 透露用户个人隐私信息。但以下特定情形除外： </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(1) 本平台根据法律法规规定或有权机关的指示提供用户的个人隐私信息； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(2) 由于用户将其用户密码告知他人或与他人共享注册帐户与密码，由此导致的任何个人信息的泄漏，或其他非因本平台原因导致的个人隐私信息的泄露； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(3) 用户自行向第三方公开其个人隐私信息；</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(4) 用户与本平台及合作单位之间就用户个人隐私信息的使用公开达成约定，本平台因此向合作单位公开用户个人隐私信息； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(5) 任何由于黑客攻击、电脑病毒侵入及其他不可抗力事件导致用户个人隐私信息的泄露。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">5. 用户同意本平台可在以下事项中使用用户的个人隐私信息： </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(1) 本平台向用户及时发送重要通知，如软件更新、本协议条款的变更； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(2) 本平台内部进行审计、数据分析和研究等，以改进本平台的产品、服务和与用户之间的沟通；用户基本信息在平台的展示（不包含各项证件的证件内容）； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(3) 依本协议约定，本平台管理、审查用户信息及进行处理措施； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(4) 适用法律法规规定的其他事项。 除上述事项外，如未取得用户事先同意，本平台不会将用户个人隐私信息使用于任何其他用途。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">6. 为了改善本平台的技术和服务，向用户提供更好的服务体验，本平台或可会自行收集使用或向第三方提供用户的非个人隐私信息(包括但不限于照片、文字、交友成功用户的成功故事等)。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">四、内容规范 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">1. 本条所述内容是指用户使用本服务过程中所制作、上载、复制、发布、传播的任何内容，包括但不限于账号头像、名称、用户说明等注册信息及认证资料，或文字、语音、图片、视频、图文等发送、回复或自动回复消息和相关链接页面，以及其他使用账号或本服务所产生的内容。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">2. 用户不得利用\"{{appName}}\"账号或本服务制作、上载、复制、发布、传播如下法律、法规和政策禁止的内容： (1) 反对宪法所确定的基本原则的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(2) 危害国家安全，泄露国家秘密，颠覆国家政权，破坏国家统一的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(3) 损害国家荣誉和利益的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(4) 煽动民族仇恨、民族歧视，破坏民族团结的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(5) 破坏国家宗教政策，宣扬邪教和封建迷信的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(6) 散布谣言，扰乱社会秩序，破坏社会稳定的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(7) 散布淫秽、色情、赌博、暴力、凶杀、恐怖或者教唆犯罪的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(8) 侮辱或者诽谤他人，侵害他人合法权益的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(9) 不遵守法律法规底线、社会主义制度底线、国家利益底线、公民合法权益底线、社会公共秩序底线、道德风尚底线和信息真实性底线的\"七条底线\"要求的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(10) 含有法律、行政法规禁止的其他内容的信息。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">3. 用户不得利用\"{{appName}}\"账号或本服务制作、上载、复制、发布、传播如下干扰\"{{appName}}\"正常运营，以及侵犯其他用户或第三方合法权益的内容： </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(1) 含有任何性或性暗示的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(2) 含有辱骂、恐吓、威胁内容的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(3) 含有骚扰、垃圾广告、恶意信息、诱骗信息的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(4) 涉及他人隐私、个人信息或资料的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(5) 侵害他人名誉权、肖像权、知识产权、商业秘密等合法权利的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(6) 含有其他干扰本服务正常运营和侵犯其他用户或第三方合法权益内容的信息。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">五、使用规则</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">1. 用户在本服务中或通过本服务所传送、发布的任何内容并不反映或代表，也不得被视为反映或代表本平台的观点、立场或政策，本平台对此不承担任何责任。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">2. 用户不得利用\"{{appName}}\"账号或本服务进行如下行为： </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(1) 提交、发布虚假信息，或盗用他人头像或资料，冒充、利用他人名义的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(2) 强制、诱导其他用户关注、点击链接页面或分享信息的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(3) 虚构事实、隐瞒真相以误导、欺骗他人的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(4) 利用技术手段批量建立虚假账号的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(5) 利用\"{{appName}}\"账号或本服务从事任何违法犯罪活动的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(6) 制作、发布与以上行为相关的方法、工具，或对此类方法、工具进行运营或传播，无论这些行为是否为商业目的； </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(7) 其他违反法律法规规定、侵犯其他用户合法权益、干扰\"{{appName}}\"正常运营或本平台未明示授权的行为。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">3. 用户须对利用\"{{appName}}\"账号或本服务传送信息的真实性、合法性、无害性、准确性、有效性等全权负责，与用户所传播的信息相关的任何法律责任由用户自行承担，与本平台无关。如因此给本平台或第三方造成损害的，用户应当依法予以赔偿。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">4. 本平台提供的服务中可能包括广告，用户同意在使用过程中显示本平台和第三方供应商、合作伙伴提供的广告。除法律法规明确规定外，用户应自行对依该广告信息进行的交易负责，对用户因依该广告信息进行的交易或前述广告商提供的内容而遭受的损失或损害，本平台不承担任何责任。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">六、用户权利 用户对于自己的个人资料享有以下权利: </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(1) 随时查询及请求阅览，但因极少数特殊情况(如被网站加入黑名单等)无法查询及提供阅览的除外; </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(2) 随时请求补充或更正，但因极少数特殊情况(如网站或有关机关为司法程序保全证据等)无法补充或更正的除外; </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(3) 随时请求注销账号。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">七、数据储存</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">1、本平台不对用户在本服务中相关数据的删除或储存失败负责。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">2、本平台可以根据实际情况自行决定用户在本服务中数据的最长储存期限，并在服务器上为其分配数据最大存储空间等。用户可根据自己的需要自行备份本服务中的相关数据。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">3、如用户停止使用本服务或本服务终止，本平台可以从服务器上永久地删除用户的数据。本服务停止、终止后，本平台没有义务向用户返还任何数据。</span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">八、法律责任和免责 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">1.本平台不保证\"{{appName}}\"服务一定能满足用户的要求，也不保证服务不会中断，对服务的及时性、安全性、真实性、出错发生都不作保证。用户理解并接受下载或通过\"{{appName}}\"服务取得任何信息资料取决于用户自己，并由其承担系统受损、资料丢失以及其它任何风险。对在任何情况下因使用或不能使用\"{{appName}}\"服务所产生的直接、间接、偶然、特殊及后续的损害及风险，本平台及合作单位不承担任何责任。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">2.本平台对用户账号上所有服务将尽力维护其安全性及方便性，但对服务中出现的信息(包括但不限于用户发布的信息)删除或储存失败不承担任何责任。另外我们保留判定用户的行为是否符合本协议的权利。如果用户违背了本协议的规定，本平台有权中止或终止对其\"{{appName}}\"帐号的服务。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">3.使用\"{{appName}}\"服务涉及到互联网服务，可能会受到各个环节不稳定因素的影响，存在因不可抗力、计算机病毒、黑客攻击、系统不稳定、用户所在位置、用户关机以及其他任何网络、技术、通信线路等原因造成的服务中断或不能满足用户要求的风险，用户须明白并自行承担以上风险，本平台不承担任何责任。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">4.用户因第三方如电信部门的通讯线路故障、技术问题、网络、电脑故障、系统不稳定性及其他各种不可抗力原因而遭受的经济损失，本平台不承担任何责任。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">5.因技术故障等事件影响到服务正常运行的，本平台承诺在第一时间内与相关单位配合，及时处理进行修复，但用户因此而遭受的经济损失，本平台不承担任何责任。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">6.用户违反本协议或相关的规则，导致或产生的任何第三方主张的任何索赔、要求或损失，包括合理的诉讼费用、律师费用以及必要的调查费用等，用户同意赔偿本平台与合作公司、关联公司，并使之免受损害。对此，本平台有权视用户的行为性质，采取包括但不限于中断使用许可、停止提供服务、限制使用、法律责任追究等措施。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">7.用户了解并同意，本平台不对因下述任一情况而导致用户的任何损害赔偿承担责任： </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(1)使用或未能使用\"{{appName}}\"服务。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(2)第三方未经批准的使用用户的账号或更改用户的数据。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(3)用户对\"{{appName}}\"服务的误解。 </span></p><p><span style=\"color: rgb(0, 0, 0); font-size: 16px;\">(4)任何非因\"{{appName}}\"的原因而引起的与\"{{appName}}\"服务有关的其它损失。 </span></p><p><span style=\"color: 